import{_ as t,c as a,o as r,a9 as i}from"./chunks/framework.Bqk8xQPS.js";const g=JSON.parse('{"title":"Sandbox Driver Selection Guide","description":"","frontmatter":{},"headers":[],"relativePath":"api/_media/DRIVERS.md","filePath":"api/_media/DRIVERS.md","lastUpdated":1773933095000}'),l={name:"api/_media/DRIVERS.md"};function n(o,e,s,d,c,p){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="sandbox-driver-selection-guide" tabindex="-1">Sandbox Driver Selection Guide <a class="header-anchor" href="#sandbox-driver-selection-guide" aria-label="Permalink to “Sandbox Driver Selection Guide”">​</a></h1><p>This guide helps you choose the right virtualization backend for your <code>@purista/sandbox</code> implementation.</p><h2 id="comparison-table" tabindex="-1">Comparison Table <a class="header-anchor" href="#comparison-table" aria-label="Permalink to “Comparison Table”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Driver</th><th style="text-align:left;">Best For</th><th style="text-align:left;">OS Support</th><th style="text-align:left;">License</th><th style="text-align:left;">Performance</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Docker</strong></td><td style="text-align:left;">General Development</td><td style="text-align:left;">Mac, Linux, Windows</td><td style="text-align:left;">Proprietary (Desktop)</td><td style="text-align:left;">High</td></tr><tr><td style="text-align:left;"><strong>Podman</strong></td><td style="text-align:left;">Security-First Containers</td><td style="text-align:left;">Mac, Linux</td><td style="text-align:left;">Apache 2.0</td><td style="text-align:left;">High</td></tr><tr><td style="text-align:left;"><strong>Lima</strong></td><td style="text-align:left;">Experimental open-source Mac VM</td><td style="text-align:left;">Mac (Apple Silicon)</td><td style="text-align:left;">Apache 2.0</td><td style="text-align:left;">Native</td></tr><tr><td style="text-align:left;"><strong>Tart</strong></td><td style="text-align:left;">Experimental Apple virtualization</td><td style="text-align:left;">Mac (Apple Silicon)</td><td style="text-align:left;">Proprietary (Free/Paid)</td><td style="text-align:left;">Native</td></tr><tr><td style="text-align:left;"><strong>Firecracker</strong></td><td style="text-align:left;">Experimental Linux microVM</td><td style="text-align:left;">Linux Bare-Metal</td><td style="text-align:left;">Apache 2.0</td><td style="text-align:left;">Highest</td></tr></tbody></table><hr><h2 id="_1-dockersandboxdriver" tabindex="-1">1. DockerSandboxDriver <a class="header-anchor" href="#_1-dockersandboxdriver" aria-label="Permalink to “1. DockerSandboxDriver”">​</a></h2><p>The default choice for most users. Compatible with Docker Desktop, OrbStack, and Colima.</p><ul><li><strong>Pros</strong>: Easy setup, huge ecosystem, consistent behavior.</li><li><strong>Cons</strong>: Docker Desktop requires a paid license for large organizations.</li></ul><h2 id="_2-limasandboxdriver-experimental" tabindex="-1">2. LimaSandboxDriver (Experimental) <a class="header-anchor" href="#_2-limasandboxdriver-experimental" aria-label="Permalink to “2. LimaSandboxDriver (Experimental)”">​</a></h2><p>A 100% open-source alternative for Apple Silicon that uses the native Apple Virtualization Framework (<code>vz</code>).</p><ul><li><strong>Pros</strong>: No licensing fees, native performance, very lightweight.</li><li><strong>Cons</strong>: Requires <code>limactl</code> to be installed on the host; restart reconciliation is disabled because owner metadata cannot be recovered safely.</li></ul><h2 id="_3-podmansandboxdriver" tabindex="-1">3. PodmanSandboxDriver <a class="header-anchor" href="#_3-podmansandboxdriver" aria-label="Permalink to “3. PodmanSandboxDriver”">​</a></h2><p>Excellent for environments where security and rootless operation are priorities.</p><ul><li><strong>Pros</strong>: Daemonless, rootless by default, open source.</li><li><strong>Cons</strong>: Slight differences in networking and volume handling compared to Docker.</li></ul><h2 id="_4-tartsandboxdriver-experimental" tabindex="-1">4. TartSandboxDriver (Experimental) <a class="header-anchor" href="#_4-tartsandboxdriver-experimental" aria-label="Permalink to “4. TartSandboxDriver (Experimental)”">​</a></h2><p>Uses Apple virtualization with Tart images.</p><ul><li><strong>Pros</strong>: Native Apple virtualization workflow.</li><li><strong>Cons</strong>: Restart reconciliation is disabled because owner metadata cannot be recovered safely.</li></ul><h2 id="_5-firecrackersandboxdriver-experimental" tabindex="-1">5. FirecrackerSandboxDriver (Experimental) <a class="header-anchor" href="#_5-firecrackersandboxdriver-experimental" aria-label="Permalink to “5. FirecrackerSandboxDriver (Experimental)”">​</a></h2><p>Provides a starting point for Linux microVM isolation.</p><ul><li><strong>Pros</strong>: Strong isolation model.</li><li><strong>Cons</strong>: Requires Linux KVM support; command execution and file-transfer handling are still incomplete.</li></ul>',20)])])}const h=t(l,[["render",n]]);export{g as __pageData,h as default};
